// pico8_globals.c
//
// Single source of truth for engine state that's shared across translation
// units (the engine unity TU and the retro-go backend TU).
//
// Definitions are zero-initialised where the original statics in data.h /
// pico8api.h / sfx.c were zero-initialised by virtue of being static aggregate
// declarations.
//
// pico8_globals.h pulls in data.h, so the `to_rgb565` macro is in scope here
// and we use it for palette values to keep colours in sync with data.h.

