// --- Builtin byte arrays ----------------------------------------------------
// stdlib_stdlib_lua: PICO-8's Lua stdlib prelude, embedded as a multi-line
// text constant. Loaded into the Lua VM by init_lua() before the cart chunk
// runs so every cart sees the PICO-8-specific globals (`add`, `del`,
// `foreach`, `band`, etc.) that PICO-8 carts use. The functions that
// PICO-8 implements natively (graphics primitives, btn/btnp, map, sfx,
// printh, time, rnd, ...) remain C-side bindings set up by
// engine.cpp::registerLuaFunctions(); the prelude only handles helpers
// that have no clean C surface inside our fix32 fixed-point runtime.
//
// PICO-8 differs from baseline Lua 5.2 in three notable ways encoded here:
//   1. cos / sin take the argument in TURNS (0..1 = full 360°) rather than
//      radians. We convert by 2π via `local TWO_PI = 2 * math.pi` and
//      delegate to math.cos / math.sin.
//   2. atan2(dx, dy) reverses AND negates relative to math.atan2(y, x)
//      because PICO-8's screen-space y-axis points down. The formula is
//      `atan2_p8(dx, dy) = -math.atan2(-dy, dx)`.
//   3. cos / sin / atan2 / sqrt are exposed as bare globals rather than
//      through math.*, matching how PICO-8 carts call them.
//
// Block strings [[..]] are used wherever a string literal would otherwise
// demand C-string backslash-escaped quotes; every other line carries only
// C-string-clean characters (`=`, `(`, `)`, `*`, `/`, `~`, `^`, `<`, `>`,
// `,`, `:`, `.`, `;`, alphanumeric, whitespace). No `"` or `\` appear.
//
// The matching `extern const …` prototypes live in pico8_globals.h (with
// incomplete array size `[]`). External linkage is inherited from the
// header declaration — re-applying `extern` here is redundant and triggers
// `-Wredundant-decls` warnings, so we omit it.
const uint8_t stdlib_stdlib_lua[] =
    "-- pico8 lua stdlib prelude (see pico8_globals.c for context)\n"
    "\n"
    "local TWO_PI = 2 * math.pi\n"
    "unpack = table.unpack\n"
    "yield = coroutine.yield\n"
    "cocreate = coroutine.create\n"
    "coresume = coroutine.resume\n"
    "costatus = coroutine.status\n"
    "\n"
    "-- PICO-8 trig (turn-based; convert to radians before delegating).\n"
    "function cos(x) return math.cos(x * TWO_PI) end\n"
    "function sin(x) return math.sin(x * TWO_PI) end\n"
    "-- atan2 reverses and negates dy for PICO-8's screen-down y-axis.\n"
    "function atan2(dx, dy) return -math.atan2(-dy, dx) end\n"
    "function sqrt(x) return math.sqrt(x) end\n"
    "\n"
    "-- Numeric aliases (PICO-8 redefines these as bare globals).\n"
    "function flr(x) if x == nil then return 0 end return math.floor(x) end\n"
    "function ceil(x) return math.ceil(x) end\n"
    "function abs(x) return x < 0 and -x or x end\n"
    "-- max(a, b) / min(a, b): guard nil args. PICO-8 defaults a missing\n"
    "-- second operand to zero, so max(x) clamps x to >=0 and min(x) clamps\n"
    "-- x to <=0. Poom relies on max(timer-1) to keep its palette-bank timer\n"
    "-- at zero; returning x unchanged makes the address wrap below 0x4400.\n"
    "-- The bare-ternary form\n"
    "--   `return a > b and a or b` produces a per-frame `attempt to compare\n"
    "-- nil with number` (`[string \"stdlib\"]:16`) whenever a cart calls\n"
    "-- max() / min() with a missing operand (e.g. `max(player.x, target.x)`\n"
    "-- where `player` has just been removed mid-frame). Celeste Classic 2\n"
    "-- hits this every frame inside `_update`. Preserve the first-operand nil\n"
    "-- passthrough for that case, but apply the documented zero default to b.\n"
    "function max(a, b)\n"
    "  if a == nil then return b end\n"
    "  if b == nil then b = 0 end\n"
    "  return a > b and a or b\n"
    "end\n"
    "function min(a, b)\n"
    "  if a == nil then return b end\n"
    "  if b == nil then b = 0 end\n"
    "  return a < b and a or b\n"
    "end\n"
    "\n"
    "function sgn(x)\n"
    "  if x > 0 then return 1 end\n"
    "  if x < 0 then return -1 end\n"
    "  return 0\n"
    "end\n"
    "\n"
    "function mid(a, b, c)\n"
    "  if a > b then a, b = b, a end\n"
    "  if b > c then b, c = c, b end\n"
    "  if a > b then a, b = b, a end\n"
    "  return b\n"
    "end\n"
    "\n"
    "-- Bit shifts. shl / shr / lshr are documented for non-negative\n"
    "-- inputs; PICO-8 cart usage of these is typically 0..2^24 range.\n"
    "function shl(a, n) return a * (2 ^ n) end\n"
    "function lshr(a, n) return math.floor(a / (2 ^ n)) end\n"
    "function shr(a, n)\n"
    "  if a >= 0 then return math.floor(a / (2 ^ n)) end\n"
    "  return -math.floor((-a) / (2 ^ n))\n"
    "end\n"
    "\n"
    "-- Bitwise ops via decimal decomposition. fix32's `/` truncates, so\n"
    "-- each `(x - xb) / 2` step is exact for non-negative integer x and\n"
    "-- the loop terminates within ceil(log2(max_input)) iterations.\n"
    "function band(a, b)\n"
    "  local x, y, p, r = a, b, 1, 0\n"
    "  while x ~= 0 and y ~= 0 do\n"
    "    local xb, yb = x % 2, y % 2\n"
    "    if xb ~= 0 and yb ~= 0 then r = r + p end\n"
    "    x = (x - xb) / 2\n"
    "    y = (y - yb) / 2\n"
    "    p = p * 2\n"
    "  end\n"
    "  return r\n"
    "end\n"
    "\n"
    "function bor(a, b)\n"
    "  local x, y, p, r = a, b, 1, 0\n"
    "  while x ~= 0 or y ~= 0 do\n"
    "    local xb, yb = x % 2, y % 2\n"
    "    if xb ~= 0 or yb ~= 0 then r = r + p end\n"
    "    x = (x - xb) / 2\n"
    "    y = (y - yb) / 2\n"
    "    p = p * 2\n"
    "  end\n"
    "  return r\n"
    "end\n"
    "\n"
    "function bxor(a, b)\n"
    "  local x, y, p, r = a, b, 1, 0\n"
    "  while x ~= 0 or y ~= 0 do\n"
    "    local xb, yb = x % 2, y % 2\n"
    "    if (xb ~= 0) ~= (yb ~= 0) then r = r + p end\n"
    "    x = (x - xb) / 2\n"
    "    y = (y - yb) / 2\n"
    "    p = p * 2\n"
    "  end\n"
    "  return r\n"
    "end\n"
    "\n"
    "local TT = [[table]]\n"
    "\n"
    "-- add, del, deli, count, all and foreach are supplied by the native\n"
    "-- API. Keeping one implementation preserves PICO-8 return values and\n"
    "-- deletion-safe array iteration without Lua wrapper overhead.\n"
    "\n"
    "-- any(t): same value-iterator semantics as `all`, but stops as soon\n"
    "-- as it encounters a nil value (matches PICO-8's ipairs-like\n"
    "-- behaviour documented in the manual).\n"
    "any = function(t)\n"
    "  if t == nil or type(t) ~= TT then return function() end end\n"
    "  local i = 0\n"
    "  return function()\n"
    "    i = i + 1\n"
    "    if t[i] == nil then return nil end\n"
    "    return t[i]\n"
    "  end\n"
    "end\n"
    "\n"
    "-- bnot(a): bitwise NOT for PICO-8's 32-bit unsigned semantics.\n"
    "-- `0xFFFFFFFF - band(a, 0xFFFFFFFF)` keeps the result as a positive\n"
    "-- fix32 instead of sign-flipped, which is what call sites expect\n"
    "-- when chaining with `band`/`bor`.\n"
    "function bnot(a) return 0xFFFFFFFF - band(a, 0xFFFFFFFF) end\n";

const uint32_t stdlib_stdlib_lua_len = sizeof(stdlib_stdlib_lua) - 1;
// artifacts_font_lua: PICO-8 default font, embedded as a 2048-byte bitmapped
// table — 256 glyphs of 8 bytes each (one byte per row of the 8x8 glyph,
// bit 7 = leftmost pixel). Glyphs 0x20..0x7E (printable ASCII) carry the
// real atlas baked by pio0/scripts/gen_default_font.py; everything else is
// all-zero (so unknown glyphs print blank cells instead of solid color
// blocks). The layout is intentionally LINEAR (glyph `c` at
// fontsheet.sprite_data + c*8), NOT the stride-128 spritesheet layout —
// see render_text() in pico8api.c which decodes one bit per pixel for
// this storage form.
//
// Generating this blob inline would bloat the diff enormously, so the
// generator script is committed under pico8/scripts/ and the resulting C
// initialiser is regenerated by running `python3 pico8/scripts/gen_default_font.py`
// and pasting the output here. The blob grows by ~1.9 KB of .rodata, which
// is fine on the Odroid Go (it has ~4 MB flash).
